import flax.linen as nn
import jax.numpy as jnp
from jax import random
from typing import Dict, Any

def _define_hyperparameters():
    """Define hyperparameters for the LSTM model."""
    return {
        'learning_rate': 0.001,
        'hidden_dim': 256,   # Hidden state dimension of the LSTM
        'dropout_rate': 0.3
    }

class RNA_LSTM(nn.Module):
    """An LSTM network for RNA sequence modeling."""
    d_output: int
    task_type: str
    hidden_dim: int
    dropout_rate: float

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Input shape: (batch, seq_len, 4)

        # 1. LSTM layer to process the sequence
        # Flax's LSTM expects input as a list of time steps, but we can use vmap for batching.
        # A simpler approach is to use a custom LSTM cell or find a batched implementation.
        # For simplicity here, we'll use nn.LSTMCell and scan over the sequence.
        lstm_cell = nn.LSTMCell(features=self.hidden_dim)

        # Initialize hidden state and cell state
        batch_size = x.shape[0]
        carry = lstm_cell.initialize_carry(random.PRNGKey(0), (batch_size,), self.hidden_dim)

        # Scan the LSTM cell over the input sequence
        # x needs to be transposed for scan: (seq_len, batch, features)
        x_t = jnp.transpose(x, (1, 0, 2))
        carry, outputs = nn.scan(lstm_cell, variable_broadcast='params',
                                 split_rngs={'params': False})(carry, x_t)

        # Use the final hidden state as the sequence representation
        final_hidden_state = carry[0] # carry is a tuple (hidden_state, cell_state)

        # 2. Dropout and final dense layer for prediction
        out = nn.Dropout(rate=self.dropout_rate)(final_hidden_state, deterministic=deterministic)
        out = nn.Dense(features=self.d_output)(out)

        # 3. Squeeze output for single-output regression tasks
        if self.task_type == "regression":
            return out.squeeze(axis=-1)
        else:
            return out

class LSTMNetwork:
    """Wrapper for the RNA_LSTM model."""
    def __init__(self, **kwargs):
        self.network = RNA_LSTM(**kwargs)

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    """Factory function to create the LSTM model."""
    return LSTMNetwork(
        d_output=hparams['d_output'],
        task_type=hparams['task_type'],
        hidden_dim=hparams['hidden_dim'],
        dropout_rate=hparams['dropout_rate']
    )

